111	function matchesToolPattern(toolName: string, pattern: string): boolean {
112	  const normalizedTool = normalizeToolName(toolName);
113	  const normalizedPattern = pattern.trim();
114	  const normalizedPatternLower = normalizedPattern.toLowerCase();
115	
116	  if (normalizedPattern === "*") {
