210	/**
211	 * Split a shell command into its individual sub-commands.
212	 *
213	 * A prefix-only allow/deny check is trivially bypassed by command chaining and
214	 * substitution: an allowed prefix (`git status`) followed by `;`, `&&`, `||`,
215	 * `|`, a newline, `$( … )`, or backticks runs an arbitrary second command that
216	 * the policy never inspects. To close that hole we evaluate the prefix check
217	 * against EVERY sub-command, not just the leading one.
218	 *
219	 * This is a deliberately conservative lexer — not a full shell parser. It walks
220	 * the string tracking single/double quotes and treats any of the shell control
221	 * operators, plus the boundaries of `$( … )` / backtick substitutions, as
222	 * segment separators. Substitution boundaries are split rather than recursed so
223	 * the substituted command body is checked as its own segment. Quoted operators
224	 * (e.g. `echo "a; b"`) are intentionally left intact — they are data, not a new
225	 * command — while unquoted ones start a new segment.
226	 */
227	function splitShellCommands(command: string): string[] {
228	  const segments: string[] = [];
229	  let current = "";
230	  let inSingle = false;
231	  let inDouble = false;
232	
233	  const push = () => {
234	    const trimmed = current.trim();
235	    if (trimmed) {
236	      segments.push(trimmed);
237	    }
238	    current = "";
239	  };
240	
241	  for (let i = 0; i < command.length; i++) {
242	    const ch = command[i];
243	    const next = command[i + 1];
244	
245	    if (inSingle) {
246	      if (ch === "'") {
247	        inSingle = false;
248	      } else {
249	        current += ch;
250	      }
251	      continue;
252	    }
253	
254	    if (inDouble) {
255	      // Inside double quotes only `$( … )` / backticks introduce a new command;
256	      // everything else (including `;`, `&&`, `|`) is literal data.
257	      if (ch === '"') {
258	        inDouble = false;
259	      } else if (ch === "$" && next === "(") {
260	        push();
261	        i++; // consume "("
262	      } else if (ch === "`") {
263	        push();
264	      } else {
265	        current += ch;
266	      }
267	      continue;
268	    }
269	
270	    if (ch === "'") {
271	      inSingle = true;
272	      continue;
273	    }
274	    if (ch === '"') {
275	      inDouble = true;
276	      continue;
277	    }
278	
279	    // Command-substitution boundaries become segment separators so the
280	    // substituted body is checked on its own.
281	    if (ch === "$" && next === "(") {
282	      push();
283	      i++; // consume "("
284	      continue;
285	    }
286	    // Process substitution: `<( … )` / `>( … )` runs the inner command, so the
287	    // boundary starts a new segment and the substituted body is checked on its
288	    // own (e.g. `cat <(rm -rf /)` must not let `rm` ride inside the `cat` segment).
289	    if ((ch === "<" || ch === ">") && next === "(") {
290	      push();
291	      i++; // consume "("
292	      continue;
293	    }
294	    if (ch === ")" || ch === "`") {
295	      push();
296	      continue;
297	    }
298	
299	    // Control operators: ; & && | || and newlines.
300	    if (ch === "\n" || ch === ";") {
301	      push();
302	      continue;
303	    }
304	    if (ch === "&" || ch === "|") {
305	      push();
306	      if (next === ch) {
307	        i++; // collapse && / ||
308	      }
309	      continue;
310	    }
311	
312	    current += ch;
313	  }
314	
315	  push();
316	  return segments;
317	}
