319	export function enforceBashCommandPolicy(
320	  command: string,
321	  policy: BashCommandPolicy
322	): void {
323	  if (!command.trim()) {
324	    return;
325	  }
326	
327	  const segments = splitShellCommands(command);
328	  if (segments.length === 0) {
329	    return;
330	  }
331	
332	  const hasAllowlist = !policy.allowAll && policy.allowPrefixes.length > 0;
333	
334	  for (const segment of segments) {
335	    const normalizedSegment = segment.toLowerCase();
336	
337	    const denied = policy.denyPrefixes.some((prefix) =>
338	      normalizedSegment.startsWith(prefix.toLowerCase())
339	    );
340	    if (denied) {
341	      throw new Error("Bash command denied by policy");
342	    }
343	
344	    if (hasAllowlist) {
345	      const allowed = policy.allowPrefixes.some((prefix) =>
346	        normalizedSegment.startsWith(prefix.toLowerCase())
347	      );
348	      if (!allowed) {
349	        throw new Error("Bash command not allowed by policy");
350	      }
351	    }
352	  }
353	}
