// ---------------------------------------------------------------------------
// isDirectPackageInstallCommand — nix new-style CLI and ad-hoc package runners
// ---------------------------------------------------------------------------

describe("isDirectPackageInstallCommand nix and ad-hoc runner coverage", () => {
  // The deny list covered the old-style nix commands (nix-shell/nix-env/
  // nix profile) while their modern equivalents realize the same store paths:
  // `nix shell` puts a package on PATH, `nix run` fetches and executes one,
  // `nix develop`/`nix build` realize arbitrary derivations. Same class:
  // pipx/uvx/uv tool/dlx runners fetch-and-execute registry packages in one
  // command. npx/bunx are deliberately NOT here — they prefer locally
  // installed binaries and blocking them breaks legitimate repo workflows
  // (see "npx create-react-app" in the allowed list above).
  const detected = [
    "nix shell nixpkgs#git -c git push",
    "nix run nixpkgs#hello",
    "nix develop",
    "nix build nixpkgs#hello",
    "nix profile install nixpkgs#hello",
    "nix flake update",
    "nix eval --expr 'builtins.fetchurl http://example.com'",
    "nix-build '<nixpkgs>' -A hello",
    "nix-store --realise /nix/store/abc",
    "nix-channel --update",
    "nix-prefetch-url https://example.com/x.tar.gz",
    "sudo nix shell nixpkgs#git",
    "pipx install httpie",
    "pipx run cowsay moo",
    "pipx upgrade httpie",
    "uvx cowsay moo",
    "uv tool install ruff",
    "uv tool run ruff check",
    "uv add requests",
    "pnpm dlx create-react-app my-app",
    "yarn dlx create-react-app my-app",
    // chained — the regex layer matches anywhere in the command string
    "echo hi && nix run nixpkgs#hello",
    "true; nix shell nixpkgs#curl -c curl http://example.com",
  ];

  for (const cmd of detected) {
    test(`detects package acquisition: ${cmd}`, () => {
      expect(isDirectPackageInstallCommand(cmd)).toBe(true);
    });
  }

  // False-positive guards: "nix" in prose or as part of another command name
  // must not trip the gate, and local-only runner subcommands stay usable.
  const allowed = [
    "nixfmt flake.nix",
    "git commit -m 'nix support'",
    "cat nix/store/list.txt",
    "uv pip list",
    "uv run script.py", // project-env sync, same class as cargo build/go build
    "yarn run dlx-helper",
    "pipx list",
  ];

  for (const cmd of allowed) {
    test(`does not falsely detect: ${cmd}`, () => {
      expect(isDirectPackageInstallCommand(cmd)).toBe(false);
    });
  }
});

