209	    // commands it installs are NOT derivable from that name, so they come from
210	    // the explicit listing above.
211	    .map((name) => name.split(/[.#]/).pop() ?? "")
212	    .flatMap((pkg) => IMAGE_BAKED_EXECUTABLES.get(pkg) ?? []);
