124	 * Remove shell backslash-escaping so an escaped executable name is matched by
125	 * its real, canonical form. The shell drops a backslash before an ordinary
126	 * character (`n\ix` → `nix`, `u\vx` → `uvx`), so without this a single
127	 * backslash bypasses the whole package-install gate. We collapse `\<char>` to
128	 * `<char>` for every character; this is intentionally broad — it can only make
129	 * the detector match MORE, never introduce a false negative, and the segment
130	 * has already been split out of any quotes by the time we get here.
131	 */
132	/**
133	 * Canonicalize a shell segment to the token string the shell would actually
134	 * execute: remove quote DELIMITERS while joining the fragments they wrap (so
135	 * `"nix"` → `nix`, `n"i"x` → `nix`, `n'i'x` → `nix`), and drop backslash
136	 * escapes (`n\ix` → `nix`). This is the load-bearing step — the detector must
137	 * match against the canonical form, because the shell strips quoting/escaping
138	 * from executable names before running them, and matching the literal text
139	 * lets `"nix" run` / `n\ix run` slip past.
140	 *
141	 * Two forms are produced:
142	 *   - `code`: the full canonical command, for matching a segment that IS a
143	 *     command (the default, fail-closed).
144	 *   - `dataStripped`: the same but with the CONTENTS of quoted spans removed
145	 *     (not just the delimiters), for a segment whose leading command treats its
146	 *     quoted arguments as data (`echo`, `git`, …) — so a package name inside a
147	 *     commit message is not a false positive.
148	 */
149	function canonicalizeSegment(segment: string): {
150	  code: string;
151	  dataStripped: string;
152	} {
153	  let code = "";
154	  let dataStripped = "";
155	  let quote: '"' | "'" | null = null;
156	  for (let i = 0; i < segment.length; i++) {
157	    const ch = segment[i];
158	    // Backslash escape: the next char is literal. Inside single quotes the
159	    // backslash is itself literal (POSIX), but treating it as an escape here
160	    // only ever removes a char from what we match, which cannot hide a command
161	    // name — conservative in the safe direction.
162	    if (ch === "\\" && i + 1 < segment.length) {
163	      code += segment[i + 1];
164	      if (!quote) {
165	        dataStripped += segment[i + 1];
166	      }
167	      i++;
168	      continue;
169	    }
170	    if (quote) {
171	      if (ch === quote) {
172	        quote = null;
173	      } else {
174	        // Quoted CONTENT is kept in `code` (it is part of the token / program)
175	        // but dropped from `dataStripped` (it is a data argument there).
176	        code += ch;
177	      }
178	      continue;
179	    }
180	    if (ch === '"' || ch === "'") {
181	      quote = ch;
182	      continue;
183	    }
184	    code += ch;
185	    dataStripped += ch;
186	  }
187	  return {
188	    code: code.trim().toLowerCase(),
189	    dataStripped: dataStripped.trim().toLowerCase(),
