// ---------------------------------------------------------------------------
// Exec wrappers (env, xargs, find, timeout, …) re-exec an arbitrary argv with
// the worker's PATH, so a registered wrapper could relaunch a deliberately
// filtered interpreter (`env sh`, `env nix`) and defeat the filter. They are in
// UNSANDBOXED_INTERPRETERS, so discovery drops them by default — proven here by
// putting a fixture `env` on a /nix/store-shaped PATH and asserting the agent's
// bash never registers it (default) yet does register it under the explicit
// opt-in (which is what makes this a real assertion, not a vacuous 127). (r5.)
// ---------------------------------------------------------------------------
describe("exec wrappers are filtered from discovery by default", () => {
  function seedFixtureWrapper(): { workspace: string; storeBin: string } {
    const workspace = fs.realpathSync(
      fs.mkdtempSync(path.join(os.tmpdir(), "lobu-wrapper-"))
    );
    tempDirs.push(workspace);
    // A /nix/store-shaped dir is required: discoverBinaries only scans PATH
    // entries containing "/nix/store/".
    const storeBin = path.join(workspace, "nix", "store", "aaaa-env", "bin");
    fs.mkdirSync(storeBin, { recursive: true });
    const fakeEnv = path.join(storeBin, "env");
    // Prints a sentinel if it ever runs; passes its args through so a re-exec
    // would be observable.
    fs.writeFileSync(fakeEnv, '#!/bin/sh\necho "WRAPPER-RAN"\n', "utf8");
    fs.chmodSync(fakeEnv, 0o755);
    return { workspace, storeBin };
  }

  test("default: fixture env is filtered, so `env` exits 127", async () => {
    const { workspace, storeBin } = seedFixtureWrapper();
    process.env.PATH = `${storeBin}:${process.env.PATH ?? ""}`;
    // Opt-in ON only to force registration to be ENABLED without a real OS
    // sandbox; the discovery FILTER still applies to UNSANDBOXED_INTERPRETERS…
    // no — the opt-in also bypasses the filter. So to test the default filter we
    // must leave the opt-in OFF and rely on a real sandbox for registration.
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    process.env.LOBU_EXEC_SANDBOX = realSandboxAvailable ? "" : "off";
    resetSandboxProbeForTests();

    const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
    const chunks: string[] = [];
    const result = await ops.exec("env true", "/", {
      onData: (chunk) => chunks.push(chunk.toString()),
      timeout: 5,
    });
    // Filtered from discovery → never registered → command not found.
    expect(result.exitCode).toBe(127);
    expect(chunks.join("")).not.toContain("WRAPPER-RAN");
  });

  test("opt-in ON: the same fixture env IS discovered (assertion is real)", async () => {
    const { workspace, storeBin } = seedFixtureWrapper();
    process.env.PATH = `${storeBin}:${process.env.PATH ?? ""}`;
    // Opt-in bypasses the filter, so `env` is registered; this proves the
    // default-case 127 above is the FILTER at work, not a missing fixture.
    registerWithoutOsSandbox();

    const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
    const chunks: string[] = [];
    const result = await ops.exec("env true", "/", {
      onData: (chunk) => chunks.push(chunk.toString()),
      timeout: 5,
    });
    // Registered → not a 127 "command not found". (It may or may not print the
    // sentinel depending on the sandbox wrapper, but it resolved the command.)
    expect(result.exitCode).not.toBe(127);
  });
});

