    // would bypass the filter, so it must stay off here.) With a real sandbox
    // registration is enabled and the filter is what yields 127; with no real
    // sandbox nothing registers at all — 127 either way, and the opt-in-ON test
    // below proves the fixture is otherwise discoverable.
    delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
    delete process.env.LOBU_EXEC_SANDBOX;
    resetSandboxProbeForTests();

    const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
    const chunks: string[] = [];
    const result = await ops.exec("env true", "/", {
      onData: (chunk) => chunks.push(chunk.toString()),
      timeout: 5,
    });
