import { expect, test } from "bun:test";
import {
  buildToolPolicy,
  enforceBashCommandPolicy,
  isDirectPackageInstallCommand,
} from "./src/runtime/tool-policy";

const PM = "npm";

test("quoted data never matches, anywhere in the quote", () => {
  const allowed = [
    "git commit -m 'document nix shell support'",
    "echo 'use uvx here'",
    "git commit -m 'we should apt install curl'",
    "git commit -m 'nix shell support'",
    `git commit -m "please ${PM} install later"`,
    "echo 'pip install foo'",
    "grep -r 'uvx' .",
    "nixfmt file.nix",
    "echo hello",
  ];
  const bad = allowed.filter((c) => isDirectPackageInstallCommand(c));
  if (bad.length) console.log("FALSE POSITIVES:", bad);
  expect(bad).toEqual([]);
});

test("real installs still caught, including after operators and in -c bodies", () => {
  const denied = [
    "nix shell nixpkgs#hello",
    "nix run nixpkgs#hello",
    "nix build .#pkg",
    "nix-shell -p hello",
    "uvx cowsay",
    "pipx run black",
    "pnpm dlx cowsay",
    "uv tool install ruff",
    `${PM} install lodash`,
    "apt install curl",
    "sudo nix run x",
    "true; nix run nixpkgs#hello",
    `true && ${PM} install lodash`,
    "(nix shell nixpkgs#hello)",
    "bash -c 'nix shell nixpkgs#hello'",
    "sh -lc 'uvx cowsay'",
    `bash -c '${PM} install foo'`,
    "echo hi | nix run x",
  ];
  const missed = denied.filter((c) => !isDirectPackageInstallCommand(c));
  if (missed.length) console.log("MISSED:", missed);
  expect(missed).toEqual([]);
});

test("backslash-newline cannot split a denied prefix", () => {
  const policy = buildToolPolicy({
    toolsConfig: { bash: { deny: ["rm "] } },
  } as never).bashPolicy;
  expect(() => enforceBashCommandPolicy("r\\\nm -rf /tmp/x", policy)).toThrow();
  expect(() => enforceBashCommandPolicy("rm -rf /tmp/x", policy)).toThrow();
});

test("other escaped metacharacters still read as literal data", () => {
  const policy = buildToolPolicy({}).bashPolicy;
  // `echo foo\; nix run` is ONE echo command, not two — must stay allowed.
  expect(() =>
    enforceBashCommandPolicy("echo foo\\; nix run x", policy)
  ).not.toThrow();
  // A real operator still splits and the second segment is denied.
  expect(() =>
    enforceBashCommandPolicy("echo foo; nix run x", policy)
  ).toThrow();
});

