import { test } from "bun:test";
import {
  enforceBashCommandPolicy,
  isDirectPackageInstallCommand,
} from "./src/runtime/tool-policy";

const bs = String.fromCharCode(92);
const policy = {
  allowAll: false,
  allowPrefixes: [] as string[],
  denyPrefixes: ["rm "],
};

test("stress: hint false-positive candidates (should all be allowed)", () => {
  const shouldAllow = [
    "git commit -m 'nix shell'",
    "git commit -m 'a nix shell b'",
    "echo \"talk about uvx and pipx run\"",
    "git log --grep='apt install'",
    "sed -i 's/nix run/nix build/' README.md",
    "cat <<EOF\nnix run x\nEOF",
    "echo 'it'\"'\"'s uvx'",
    "python -c 'print(\"pip install\")'",
    "echo done # nix run x",
    "VAR='nix run x' echo hi",
    "export MSG='pipx install black'",
    "curl -d 'nix shell' https://example.com",
  ];
  for (const c of shouldAllow) {
    const hit = isDirectPackageInstallCommand(c);
    if (hit) console.log("FP?  ", JSON.stringify(c));
  }
});

test("stress: hint true-positive candidates (should all be denied)", () => {
  const shouldDeny = [
    "nix run x",
    "  nix run x",
    "nix\trun x",
    "sudo nix run x",
    "true; nix run x",
    "true && nix run x",
    "true || nix run x",
    "echo hi | uvx cowsay",
    "(nix shell x)",
    "{ nix run x; }",
    "bash -c 'nix run x'",
    "sh -lc 'uvx x'",
    "if true; then nix run x; fi",
    "for i in 1; do nix run x; done",
    "$(nix run x)",
    "nix  run  x",
  ];
  for (const c of shouldDeny) {
    const hit = isDirectPackageInstallCommand(c);
    if (!hit) console.log("MISS?", JSON.stringify(c));
  }
});

test("stress: deny-prefix evasion candidates (should all throw)", () => {
  const shouldThrow = [
    "rm -rf /tmp/x",
    `r${bs}\nm -rf /tmp/x`,
    `r${bs}\nm${bs}\n -rf /tmp/x`,
    "true; rm -rf /tmp/x",
    "true && rm -rf /tmp/x",
    "$(rm -rf /tmp/x)",
    "cat <(rm -rf /tmp/x)",
  ];
  for (const c of shouldThrow) {
    let threw = false;
    try {
      enforceBashCommandPolicy(c, policy);
    } catch {
      threw = true;
    }
    if (!threw) console.log("BYPASS?", JSON.stringify(c));
  }
});

